-- First Steps · A1
insert into public.courses (id, slug, title, title_kk, title_en, subtitle, subtitle_kk, subtitle_en, description, description_kk, description_en, level, category, glyph, cover_url, is_published, sort) values ('00000000-0000-4000-8000-000000000200', 'first-steps-a1', 'First Steps', 'First Steps', 'First Steps', 'Английский с нуля: знакомство, числа, первые фразы', 'Ағылшын тілі нөлден: танысу, сандар, алғашқы сөйлемдер', 'English from scratch: introductions, numbers, first phrases', 'Курс для тех, кто начинает с самого начала. Учимся здороваться, рассказывать о себе и понимать простые вопросы. Каждое слово можно прослушать и повторить за диктором.', 'Ең басынан бастайтындарға арналған курс. Сәлемдесуді, өзіңіз туралы айтуды және қарапайым сұрақтарды түсінуді үйренеміз. Әр сөзді тыңдап, дикторға қайталауға болады.', 'A course for complete beginners. Learn to say hello, talk about yourself and understand simple questions. You can listen to every word and repeat after the speaker.', 'A1', 'general', 'Hi!', '', true, 1) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000201', '00000000-0000-4000-8000-000000000200', 1, 'Приветствия и рассказ о себе в трёх фразах.', 'Сәлемдесу және өзіңіз туралы үш сөйлем.', 'Greetings and introducing yourself in three phrases.', 12, true, true, 'Hello! Знакомимся', 'Hello! Танысамыз', 'Hello! Let''s meet') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000201', '', '## Как представиться
В английском знакомство строится из трёх коротких фраз:
- **Hello! My name is Aruzhan.** — Привет! Меня зовут Аружан.
- **I''m from Almaty.** — Я из Алматы.
- **Nice to meet you!** — Приятно познакомиться!

Прослушайте каждую фразу, повторите вслух и запишите себя в задании ниже.', '## Қалай таныстыру керек
Ағылшын тілінде танысу үш қысқа сөйлемнен тұрады:
- **Hello! My name is Aruzhan.** — Сәлем! Менің атым Аружан.
- **I''m from Almaty.** — Мен Алматыданмын.
- **Nice to meet you!** — Танысқаныма қуаныштымын!

Әр сөйлемді тыңдап, дауыстап қайталаңыз да, төмендегі тапсырмада өзіңізді жазып алыңыз.', '## How to introduce yourself
In English, an introduction is built from three short phrases:
- **Hello! My name is Aruzhan.**
- **I''m from Almaty.**
- **Nice to meet you!**

Listen to each phrase, repeat it out loud and record yourself in the task below.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('vocabulary', 'Слова для знакомства', 'Танысу сөздері', 'Words for introductions', 'Переверните карточку, прослушайте слово и отметьте, знаете ли вы его.', 'Карточканы аударып, сөзді тыңдаңыз да, білетініңізді белгілеңіз.', 'Flip the card, listen to the word and mark whether you know it.', '{"words":[{"term":"hello","ru":"привет, здравствуйте","kk":"сәлем, сәлеметсіз бе","example":"Hello! How are you?"},{"term":"my name is","ru":"меня зовут","kk":"менің атым","example":"My name is Dana."},{"term":"nice to meet you","ru":"приятно познакомиться","kk":"танысқаныма қуаныштымын","example":"Nice to meet you, Dana!"},{"term":"where are you from?","ru":"откуда вы?","kk":"қай жерденсіз?","example":"Where are you from? — I''m from Astana."},{"term":"goodbye","ru":"до свидания","kk":"сау болыңыз","example":"Goodbye! See you tomorrow."}]}'::jsonb, '00000000-0000-4000-8000-000000020101', '00000000-0000-4000-8000-000000000201', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Скажите о себе', 'Өзіңіз туралы айтыңыз', 'Talk about yourself', 'Прослушайте фразу, запишите себя и посмотрите, какие слова распознались.', 'Сөйлемді тыңдап, өзіңізді жазып алыңыз да, қай сөздер танылғанын қараңыз.', 'Listen to the phrase, record yourself and see which words were recognised.', '{"phrases":[{"text":"Hello! My name is Aruzhan.","hint":"Подставьте своё имя — система проверит остальные слова.","hint_kk":"Өз атыңызды қойыңыз — жүйе қалған сөздерді тексереді.","hint_en":"Use your own name — the system will check the other words."},{"text":"I''m from Almaty.","hint":"Звук /m/ в I''m не проглатываем.","hint_kk":"I''m сөзіндегі /m/ дыбысын жұтып қоймаңыз.","hint_en":"Don''t swallow the /m/ sound in I''m."},{"text":"Nice to meet you!","hint":"Ударение на meet.","hint_kk":"Екпін meet сөзіне түседі.","hint_en":"The stress falls on meet."}]}'::jsonb, '00000000-0000-4000-8000-000000020102', '00000000-0000-4000-8000-000000000201', 2) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Проверьте себя', 'Өзіңізді тексеріңіз', 'Check yourself', 'Выберите правильный вариант.', 'Дұрыс нұсқаны таңдаңыз.', 'Choose the correct option.', '{"questions":[{"question":"— Nice to meet you! — …","options":["Nice to meet you too!","Goodbye, too!","My name is too."],"correct":0,"explanation":"На «Nice to meet you» отвечают «Nice to meet you too».","explanation_kk":"«Nice to meet you» дегенге «Nice to meet you too» деп жауап береді.","explanation_en":"The reply to “Nice to meet you” is “Nice to meet you too”."},{"question":"Where ___ you from?","options":["is","are","am"],"correct":1,"explanation":"С you всегда используется are.","explanation_kk":"you сөзімен әрқашан are қолданылады.","explanation_en":"With you we always use are."},{"question":"I ___ from Shymkent.","options":["is","are","am"],"correct":2,"explanation":"С I используется am: I am = I''m.","explanation_kk":"I сөзімен am қолданылады: I am = I''m.","explanation_en":"With I we use am: I am = I''m."}]}'::jsonb, '00000000-0000-4000-8000-000000020103', '00000000-0000-4000-8000-000000000201', 3) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000202', '00000000-0000-4000-8000-000000000200', 2, 'Числа от 0 до 20 и как продиктовать номер телефона.', '0-ден 20-ға дейінгі сандар және телефон нөмірін айту.', 'Numbers from 0 to 20 and how to say a phone number.', 10, false, true, 'Numbers & phone numbers', 'Сандар және телефон нөмірі', 'Numbers & phone numbers') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000202', '', '## Номер телефона по-английски
Цифры называют по одной: **seven, seven, zero, one…** Ноль часто читают как **oh**. Две одинаковые цифры подряд можно сказать как **double**: 77 — **double seven**.', '## Телефон нөмірі ағылшынша
Цифрларды бір-бірден атайды: **seven, seven, zero, one…** Нөлді көбіне **oh** деп оқиды. Қатар тұрған екі бірдей цифрды **double** деп айтуға болады: 77 — **double seven**.', '## Phone numbers in English
Say the digits one by one: **seven, seven, zero, one…** Zero is often read as **oh**. Two identical digits in a row can be said with **double**: 77 — **double seven**.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('vocabulary', 'Числа', 'Сандар', 'Numbers', 'Повторите числа вслух вместе с диктором.', 'Сандарды дикторға ілесіп дауыстап қайталаңыз.', 'Repeat the numbers out loud with the speaker.', '{"words":[{"term":"three","ru":"три","kk":"үш","example":"I have three sisters."},{"term":"eight","ru":"восемь","kk":"сегіз","example":"The lesson starts at eight."},{"term":"thirteen","ru":"тринадцать","kk":"он үш","example":"She is thirteen."},{"term":"thirty","ru":"тридцать","kk":"отыз","example":"Thirty minutes a day."},{"term":"double seven","ru":"две семёрки (77)","kk":"екі жеті (77)","example":"My number starts with double seven."}]}'::jsonb, '00000000-0000-4000-8000-000000020201', '00000000-0000-4000-8000-000000000202', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Продиктуйте номер', 'Нөміріңізді айтыңыз', 'Say your number', 'Скажите номер так, как его произносят носители.', 'Нөмірді тілді меңгергендер айтатындай айтыңыз.', 'Say the number the way native speakers do.', '{"phrases":[{"text":"My number is double seven oh one.","hint":"oh — так часто читают ноль.","hint_kk":"oh — нөлді көбіне осылай оқиды.","hint_en":"oh — this is how zero is often read."},{"text":"Thirteen, not thirty.","hint":"В thirteen ударение на -teen, в thirty — на thir-.","hint_kk":"thirteen сөзінде екпін -teen-ге, thirty сөзінде thir-ге түседі.","hint_en":"In thirteen the stress is on -teen, in thirty it''s on thir-."}]}'::jsonb, '00000000-0000-4000-8000-000000020202', '00000000-0000-4000-8000-000000000202', 2) on conflict do nothing;

-- Clear Pronunciation · A2
insert into public.courses (id, slug, title, title_kk, title_en, subtitle, subtitle_kk, subtitle_en, description, description_kk, description_en, level, category, glyph, cover_url, is_published, sort) values ('00000000-0000-4000-8000-000000000300', 'clear-pronunciation-a2', 'Clear Pronunciation', 'Clear Pronunciation', 'Clear Pronunciation', 'Звуки, которых нет в русском и казахском', 'Қазақ және орыс тілдерінде жоқ дыбыстар', 'Sounds that don''t exist in Russian or Kazakh', 'Тренажёр произношения: слушаете эталон, записываете себя, сразу видите, какие слова прозвучали неразборчиво, а преподаватель даёт обратную связь голосом.', 'Айтылым тренажері: эталонды тыңдайсыз, өзіңізді жазасыз, қай сөздер анық естілмегенін бірден көресіз, ал оқытушы дауыспен кері байланыс береді.', 'A pronunciation trainer: listen to the model, record yourself, instantly see which words were unclear, and get voice feedback from a teacher.', 'A2', 'speaking', '/θ/', '', true, 2) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000301', '00000000-0000-4000-8000-000000000300', 1, 'Межзубные /θ/ и /ð/: think, this, three.', 'Тіс аралық /θ/ және /ð/: think, this, three.', 'The dental sounds /θ/ and /ð/: think, this, three.', 15, true, true, 'The TH sound', 'TH дыбысы', 'The TH sound') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000301', '', '## Как поставить звук TH
Кончик языка слегка выглядывает между зубами, воздух проходит над ним.
- **/θ/** — глухой: think, three, thank you
- **/ð/** — звонкий: this, that, mother

Не заменяйте TH на «с», «з» или «ф» — так слово может превратиться в другое: **think → sink**.', '## TH дыбысын қалай қою керек
Тілдің ұшы тістің арасынан сәл көрініп тұрады, ауа оның үстінен өтеді.
- **/θ/** — қатаң: think, three, thank you
- **/ð/** — ұяң: this, that, mother

TH дыбысын «с», «з» немесе «ф» дыбысымен алмастырмаңыз — сөз басқа сөзге айналуы мүмкін: **think → sink**.', '## How to make the TH sound
The tip of your tongue peeks out slightly between your teeth, and air flows over it.
- **/θ/** — voiceless: think, three, thank you
- **/ð/** — voiced: this, that, mother

Don''t replace TH with “s”, “z” or “f” — the word can turn into a different one: **think → sink**.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Скороговорки с TH', 'TH дыбысы бар жаңылтпаштар', 'TH tongue twisters', 'Сначала прослушайте медленно, затем запишите себя.', 'Алдымен баяу тыңдап, содан кейін өзіңізді жазыңыз.', 'Listen at slow speed first, then record yourself.', '{"phrases":[{"text":"I think three is enough.","hint":"think и three — глухой /θ/.","hint_kk":"think пен three — қатаң /θ/.","hint_en":"think and three — voiceless /θ/."},{"text":"This is my mother.","hint":"this и mother — звонкий /ð/.","hint_kk":"this пен mother — ұяң /ð/.","hint_en":"this and mother — voiced /ð/."},{"text":"Thank you for the thoughtful gift.","hint":"Три TH подряд — не торопитесь.","hint_kk":"Қатарынан үш TH — асықпаңыз.","hint_en":"Three THs in a row — take your time."}]}'::jsonb, '00000000-0000-4000-8000-000000030101', '00000000-0000-4000-8000-000000000301', 1) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000302', '00000000-0000-4000-8000-000000000300', 2, 'Где ставить ударение в длинных словах.', 'Ұзын сөздерде екпінді қайда қою керек.', 'Where to put the stress in long words.', 12, false, true, 'Word stress', 'Сөздегі екпін', 'Word stress') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000302', '', '## Ударение меняет смысл
В английском ударный слог длиннее и громче, а безударные звучат коротко и нечётко.
- **PREsent** — подарок, **preSENT** — представлять
- **PHOtograph**, **phoTOgrapher**, **photoGRAPHic** — ударение «переезжает» вместе с суффиксом.', '## Екпін мағынаны өзгертеді
Ағылшын тілінде екпінді буын ұзақ әрі қатты айтылады, ал екпінсіз буындар қысқа әрі анық емес естіледі.
- **PREsent** — сыйлық, **preSENT** — ұсыну
- **PHOtograph**, **phoTOgrapher**, **photoGRAPHic** — екпін жұрнақпен бірге «көшеді».', '## Stress changes meaning
In English, the stressed syllable is longer and louder, while unstressed ones sound short and unclear.
- **PREsent** — a gift, **preSENT** — to show or introduce
- **PHOtograph**, **phoTOgrapher**, **photoGRAPHic** — the stress “moves” along with the suffix.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('pronunciation', 'Ударение в словах', 'Сөздердегі екпін', 'Stress in words', 'Выделяйте ударный слог голосом.', 'Екпінді буынды дауыспен ерекшелеңіз.', 'Stress the key syllable with your voice.', '{"phrases":[{"text":"The photographer took a beautiful photograph.","hint":"phoTOgrapher, PHOtograph","hint_kk":"phoTOgrapher, PHOtograph","hint_en":"phoTOgrapher, PHOtograph"},{"text":"I want to present my present.","hint":"preSENT (глагол), PREsent (существительное)","hint_kk":"preSENT (етістік), PREsent (зат есім)","hint_en":"preSENT (verb), PREsent (noun)"}]}'::jsonb, '00000000-0000-4000-8000-000000030201', '00000000-0000-4000-8000-000000000302', 1) on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('quiz', 'Где ударение?', 'Екпін қайда?', 'Where''s the stress?', 'Выберите вариант с правильным ударением.', 'Екпіні дұрыс қойылған нұсқаны таңдаңыз.', 'Choose the option with the correct stress.', '{"questions":[{"question":"comfortable","options":["COMfortable","comFORtable","comforTAble"],"correct":0,"explanation":"COM-fta-ble: ударение на первый слог, середина почти не звучит.","explanation_kk":"COM-fta-ble: екпін бірінші буынға түседі, ортасы дерлік естілмейді.","explanation_en":"COM-fta-ble: the stress is on the first syllable, the middle is almost silent."},{"question":"important","options":["IMportant","imPORtant","importANT"],"correct":1,"explanation":"imPORtant — ударение на второй слог.","explanation_kk":"imPORtant — екпін екінші буынға түседі.","explanation_en":"imPORtant — the stress is on the second syllable."}]}'::jsonb, '00000000-0000-4000-8000-000000030202', '00000000-0000-4000-8000-000000000302', 2) on conflict do nothing;

-- Everyday English · B1
insert into public.courses (id, slug, title, title_kk, title_en, subtitle, subtitle_kk, subtitle_en, description, description_kk, description_en, level, category, glyph, cover_url, is_published, sort) values ('00000000-0000-4000-8000-000000000100', 'everyday-english-b1', 'Everyday English', 'Everyday English', 'Everyday English', 'Истории, перемены и уверенная речь в прошедшем времени', 'Әңгімелер, өзгерістер және өткен шақта сенімді сөйлеу', 'Stories, changes and confident speaking in the past tense', 'Юнит о новых начинаниях: словарь для рассказа о переменах, past simple и past continuous, чтение, аудирование по TED-выступлению, собственная история вслух и письменно. Задания на речь и письмо проверяет преподаватель.', 'Жаңа бастамалар туралы бөлім: өзгерістер туралы айтуға арналған сөздер, past simple және past continuous, оқу, TED баяндамасы бойынша тыңдалым, өз әңгімеңізді ауызша және жазбаша айту. Сөйлеу мен жазу тапсырмаларын оқытушы тексереді.', 'A unit about new beginnings: vocabulary for talking about change, past simple and past continuous, reading, listening to a TED talk, and telling your own story out loud and in writing. A teacher checks the speaking and writing tasks.', 'B1', 'general', 'New', '', true, 3) on conflict do nothing;
insert into public.lessons (id, course_id, sort, summary, summary_kk, summary_en, minutes, is_free, is_published, title, title_kk, title_en) values ('00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000100', 1, 'Когда вы в последний раз пробовали что-то новое?', 'Соңғы рет қашан жаңа нәрсені байқап көрдіңіз?', 'When did you last try something new?', 5, true, true, 'Start here', 'Бастайық', 'Start here') on conflict do nothing;
insert into public.lesson_materials (lesson_id, video_url, body, body_kk, body_en) values ('00000000-0000-4000-8000-000000000101', 'https://www.youtube.com/watch?v=UNP03fDSj1U', '## When did you last try something new?
В этом юните вы будете говорить о переменах в жизни, понимать чужие истории и расскажете свою.

Посмотрите короткое выступление: автор 30 дней подряд пробовал что-то новое. Попробуйте уловить главную мысль — детали разберём позже.', '## When did you last try something new?
Бұл бөлімде өмірдегі өзгерістер туралы сөйлейсіз, басқалардың әңгімелерін түсінесіз және өз әңгімеңізді айтасыз.

Қысқа баяндаманы көріңіз: автор 30 күн қатарынан жаңа нәрсе байқап көрген. Негізгі ойын ұстауға тырысыңыз — егжей-тегжейін кейін талдаймыз.', '## When did you last try something new?
In this unit you''ll talk about changes in life, understand other people''s stories and tell your own.

Watch a short talk: the speaker tried something new for 30 days in a row. Try to catch the main idea — we''ll look at the details later.') on conflict do nothing;
insert into public.tasks (kind, title, title_kk, title_en, prompt, prompt_kk, prompt_en, data, id, lesson_id, sort) values ('writing', 'Разминка', 'Дайындық', 'Warm-up', 'Think of one thing you started recently. What made you begin? Напишите 2–3 предложения.', 'Think of one thing you started recently. What made you begin? 2–3 сөйлем жазыңыз.', 'Think of one thing you started recently. What made you begin? Write 2–3 sentences.', '{"min_words":15,"max_words":80,"checklist":[]}'::jsonb, '00000000-0000-4000-8000-000000010101', '00000000-0000-4000-8000-000000000101', 1) on conflict do nothing;
